<?php
/** Child resource cards shared by home and direction catalogue. */
if(PHP_SAPI!=='cli'||!in_array('--apply',$argv,true))exit("Usage: php tools/modx/configure-direction-lists.php --apply\n");
$root=dirname(__DIR__,2).'/';define('MODX_API_MODE',true);require $root.'public/index.php';$modx->initialize('mgr');
use MODX\Revolution\{modResource,modTemplate,modTemplateVar,modTemplateVarTemplate,modTemplateVarResource,modChunk,modCategory};
$home=$modx->getObject(modTemplate::class,2);$listing=$modx->getObject(modTemplate::class,5);$homeHtml=$home->get('content');$listHtml=$listing->get('content');$seedCards=[];$seedIndex=[];
function dom($html){$doc=new DOMDocument();libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8">'.$html);libxml_clear_errors();return [$doc,new DOMXPath($doc)];}
function text($xp,$path,$node=null){return trim($xp->query($path,$node)->item(0)?->textContent??'');}
function inner($doc,$node){$html='';foreach($node->childNodes as $child)$html.=$doc->saveHTML($child);return $html;}
function resourceByUrl($modx,$url){$uri=ltrim(parse_url($url,PHP_URL_PATH),'/');return $modx->getObject(modResource::class,['uri'=>$uri,'context_key'=>'web']);}
if(!str_contains($listHtml,'[[$directionChoices]]')){
 [$doc,$xp]=dom($listHtml);foreach($xp->query('//a[@class="direction-choice"]') as $card){$r=resourceByUrl($modx,$card->getAttribute('href'));if(!$r)throw new RuntimeException('Unknown direction URL');$seedCards[$r->get('id')]=['card_title'=>text($xp,'.//h2',$card),'card_description'=>text($xp,'.//p',$card),'card_image'=>ltrim(parse_url($xp->query('.//img',$card)->item(0)->getAttribute('src'),PHP_URL_PATH),'/')];}
 $intro=$xp->query('//*[@id="direction-guide-title"]')->item(0);$answers=[];foreach($xp->query('//div[@class="direction-guide__answers"]/div') as $row)$answers[]=['MIGX_id'=>count($answers)+1,'question'=>text($xp,'.//h3',$row),'answer'=>text($xp,'.//p',$row)];$links=[];foreach($xp->query('//div[@class="container directions-next__grid"]/a') as $link){$r=resourceByUrl($modx,$link->getAttribute('href'));if(!$r)throw new RuntimeException('Unknown next link');$links[]=['MIGX_id'=>count($links)+1,'title'=>trim($link->textContent),'resource'=>(int)$r->get('id')];}$seedIndex=['directions_guide'=>[['MIGX_id'=>1,'heading'=>inner($doc,$intro),'intro'=>text($xp,'//p[@class="direction-guide__intro"]')]],'directions_guide_answers'=>$answers,'directions_next_links'=>$links];
}
if(!str_contains($homeHtml,'[[$homeDirections]]')){
 [$doc,$xp]=dom($homeHtml);foreach($xp->query('//article[contains(concat(" ",normalize-space(@class)," ")," directions__card ")]') as $card){$r=resourceByUrl($modx,$xp->query('.//a',$card)->item(0)->getAttribute('href'));if(!$r)throw new RuntimeException('Unknown home direction');$description=$xp->query('.//p',$card)->item(0);foreach(iterator_to_array($description->getElementsByTagName('br')) as $br)$br->parentNode->replaceChild($doc->createTextNode("\n"),$br);$image=$xp->query('.//img',$card)->item(0);$small=explode(' ',trim(explode(',',$image->getAttribute('srcset'))[0]))[0];$seedCards[$r->get('id')]['card_home_description']=trim($description->textContent);$seedCards[$r->get('id')]['card_image_small']=ltrim(parse_url($small,PHP_URL_PATH),'/');}
}
$tv=$modx->getObject(modTemplateVar::class,['name'=>'direction_blocks']);$props=$tv->get('input_properties');$tabs=json_decode($props['formtabs'],true);$hasTab=false;foreach($tabs as $tab)if($tab['caption']==='Карточка направления')$hasTab=true;
if(!$hasTab){$image=$tabs[0]['fields'][0];$cardImage=$image;$cardImage['field']='card_image';$cardImage['caption']='Картинка карточки';$small=$cardImage;$small['field']='card_image_small';$small['caption']='Маленькая версия картинки (необязательно)';$cardTab=['caption'=>'Карточка направления','fields'=>[
 ['field'=>'card_title','caption'=>'Название карточки','inputTVtype'=>'text','description'=>'Если пусто — заголовок ресурса.'],
 ['field'=>'card_description','caption'=>'Описание в списке направлений','inputTVtype'=>'textarea'],
 ['field'=>'card_audience_description','caption'=>'Краткое описание на страницах аудитории','inputTVtype'=>'textarea'],
 ['field'=>'card_home_description','caption'=>'Краткое описание на главной','inputTVtype'=>'textarea','description'=>'Перенос строки сохраняется. Если пусто — описание из списка.'],
 $cardImage,$small,
 ]];array_splice($tabs,1,0,[$cardTab]);$props['formtabs']=json_encode($tabs,JSON_UNESCAPED_UNICODE);$tv->set('input_properties',$props);if(!$tv->save())throw new RuntimeException('Card tab save failed');}
foreach($seedCards as $id=>$values){$r=$modx->getObject(modResource::class,$id);$rows=json_decode($r->getTVValue('direction_blocks'),true);if(!$rows)$rows=[['MIGX_id'=>1]];$rows[0]+=$values;if(!$r->setTVValue('direction_blocks',json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)))throw new RuntimeException('Card seed failed');}
$category=$modx->getObject(modCategory::class,['category'=>'Направления — список']);if(!$category){$category=$modx->newObject(modCategory::class);$category->set('category','Направления — список');if(!$category->save())throw new RuntimeException('Category save failed');}
$defs=[
 'directions_guide'=>['Как выбрать направление',[['field'=>'heading','caption'=>'Заголовок','inputTVtype'=>'text','description'=>'Для красного акцента используйте span.'],['field'=>'intro','caption'=>'Вводный текст','inputTVtype'=>'textarea']]],
 'directions_guide_answers'=>['Пояснения к выбору',[['field'=>'question','caption'=>'Вопрос / заголовок','inputTVtype'=>'text'],['field'=>'answer','caption'=>'Ответ','inputTVtype'=>'textarea']]],
 'directions_next_links'=>['Полезные ссылки',[['field'=>'title','caption'=>'Название ссылки','inputTVtype'=>'text'],['field'=>'resource','caption'=>'Страница','inputTVtype'=>'listbox','inputOptionValues'=>"@SELECT pagetitle,id FROM [[+PREFIX]]site_content WHERE published=1 AND deleted=0 AND context_key='web' AND id NOT IN(2,38,39,40) ORDER BY pagetitle",'configs'=>json_encode(['allowBlank'=>false,'forceSelection'=>true])]]],
];
$file=$root.'cms/template-registry.json';$reg=json_decode(file_get_contents($file),true);foreach($defs as $name=>[$caption,$fields]){$tv=$modx->getObject(modTemplateVar::class,['name'=>$name])?:$modx->newObject(modTemplateVar::class);$columns=[];foreach($fields as $field)$columns[]=['header'=>$field['caption'],'dataIndex'=>$field['field'],'width'=>300,'renderer'=>'Ext.util.Format.htmlEncode'];$tv->fromArray(['name'=>$name,'caption'=>$caption,'type'=>'migx','category'=>$category->get('id'),'default_text'=>'','display'=>'default','rank'=>array_search($name,array_keys($defs)),'input_properties'=>['formtabs'=>json_encode([['caption'=>$caption,'fields'=>$fields]],JSON_UNESCAPED_UNICODE),'columns'=>json_encode($columns,JSON_UNESCAPED_UNICODE),'btntext'=>'Добавить запись']]);if(!$tv->save())throw new RuntimeException('Index TV save failed');$id=(int)$tv->get('id');$reg['fields'][$name]=$id;$criteria=['templateid'=>5,'tmplvarid'=>$id];if(!$modx->getObject(modTemplateVarTemplate::class,$criteria)){$link=$modx->newObject(modTemplateVarTemplate::class);$link->fromArray($criteria,'',true,true);if(!$link->save())throw new RuntimeException('Index TV assignment failed');}foreach($modx->getCollection(modResource::class,['template'=>5,'deleted'=>0]) as $r)if(!$modx->getObject(modTemplateVarResource::class,['tmplvarid'=>$id,'contentid'=>$r->get('id')])){if(!isset($seedIndex[$name]))throw new RuntimeException('Index seed missing');$r->setTVValue($name,json_encode($seedIndex[$name],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}}
$names=['homeDirections','directionChoices','directionHomeItem','directionHomeCard','directionListingItem','directionListingCard','directionsGuide','directionsGuideAnswer','directionsNext','directionsNextLink'];$common=$modx->getObject(modCategory::class,['category'=>'Общие'])->get('id');foreach($names as $name){$c=$modx->getObject(modChunk::class,['name'=>$name])?:$modx->newObject(modChunk::class);$c->fromArray(['name'=>$name,'category'=>$common,'snippet'=>file_get_contents($root.'cms/chunks/'.$name.'.html')]);if(!$c->save())throw new RuntimeException('Chunk save failed');}
if(!str_contains($homeHtml,'[[$homeDirections]]')){$homeHtml=preg_replace('~<section class="section directions".*?</section>~s','[[$homeDirections]]',$homeHtml,-1,$count);if($count!==1)throw new RuntimeException('Home section mismatch');$home->set('content',$homeHtml);$home->save();}
if(!str_contains($listHtml,'[[$directionChoices]]')){$listHtml=preg_replace('~<section class="section" aria-label="Направления ZUBR GYM">.*?</section>~s','[[$directionChoices]]',$listHtml,1);$listHtml=preg_replace('~<section class="section direction-guide".*?</section>~s','[[!getImageList? &tvname=`directions_guide` &tpl=`directionsGuide` &limit=`1` &processTVs=`0` &totalVar=`directionsGuideBlocksTotal`]]',$listHtml,1);$listHtml=preg_replace('~<section class="section directions-next".*?</section>~s','[[$directionsNext]]',$listHtml,1);$listing->set('content',$listHtml);$listing->save();}
$reg['chunks']=array_values(array_unique(array_merge($reg['chunks'],$names)));file_put_contents($file,json_encode($reg,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$modx->cacheManager->refresh();echo "Dynamic child direction cards applied to home and catalogue.\n";

